<span class="line">    <span class="token key atrule">command</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;-host=0.0.0.0&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;-config=/etc/toxiproxy/config.json&#39;</span><span class="token punctuation">]</span></span>
